/* বাংলা সংস্করণ — এক ফাইলে।

   The Bangla edition. Key for key the same set as en.js, in the same order, so the two
   can be read side by side and scripts/check_i18n.js can fail on any key one has and
   the other lacks. Where an entry takes numbers it is a function of them, because the
   sentence is rebuilt in Bengali word order rather than substituted into an English
   frame: the verb goes last, the unit goes after the figure, and a count and the thing
   counted change places. The digits themselves arrive already written — num(), pct()
   and taka() in components/ui.js format them with Intl for "bn-BD", so a figure reads
   ১,১৫০ and ৩৭,২০,০০,০০,০০০ without anything here doing arithmetic.

   যা অনুবাদ করা হয়নি, এবং কেন। এই সংস্করণে অনেক শব্দ ইংরেজিতেই থাকে, এবং সেটি ভুল নয় —
   সেগুলিই প্রমাণ। প্রতিষ্ঠানের নাম, ব্যক্তির নাম, দরপত্রের নম্বর, PDF ফাইলের নাম, নোটিশে
   ছাপা অবস্থা, উদ্ধৃত ধারার শব্দ, পোর্টালের নিজের ফর্মের ঘরের নাম, এবং তথ্যভান্ডারের
   কলামের শিরোনাম — এগুলি কাগজে যেভাবে ছাপা, ঠিক সেভাবেই থাকে। যে পাঠক কোনো সংখ্যা PDF-এর
   ৩ নম্বর পৃষ্ঠার সঙ্গে মিলিয়ে দেখতে চান, তাঁকে এখানে ঠিক সেই অক্ষরগুলিই পেতে হবে; অনুবাদ
   করা নাম কোথাও খুঁজে পাওয়া যাবে না। পৃষ্ঠায় যেখানে পাঠক প্রথম এমন একটি শব্দের মুখোমুখি
   হন, সেখানেই কথাটি লেখা আছে — "bn.note.*" দেখুন।

   __data, at the end of this file, is the other half of the same rule: 04_analysis.py
   and 03_audit.py write sentences into the dataset in English, keyed by nothing, so the
   map from the exact English sentence to its Bangla counterpart lives there. A sentence
   with no entry prints in English, which a reader can still read; a placeholder could
   not be read at all. Which families are covered and which are deliberately left is
   written above the map. */

