  "file.master": "মাস্টার তথ্যভান্ডার (CSV)",
  "file.master.what": "প্রতিটি সারণির প্রতিটি সারি এক ফাইলে।",
  "file.analysis": "এই সাইটের প্রতিটি হিসাব (JSON)",
