  "file.qa": "সম্পাদকের যাচাই প্রতিবেদন",
  "file.qa.what": "এর কিছু প্রকাশের আগে একজন সম্পাদকের যা যাচাই করা উচিত।",
  "file.pages": "তুলে আনা লেখা, পৃষ্ঠা ধরে",
  "file.pages.what": "পার্সার আসলে যা পড়েছে, ভুলগুলি না শুধরে।",
