  /* ---- chapter six: the rule of entry against the result ---- */

  "ch6.kicker": "অধ্যায় ছয়",
  "ch6.title": "প্রবেশের শর্ত, ফলাফলের বিপরীতে",
  "ch6.p1": ({ tenders }) =>
    "চার নম্বর অধ্যায় দেখিয়েছে প্রবেশের কোন শর্তগুলি আলাদা হয়ে দাঁড়ায়। পাঁচ নম্বর অধ্যায় "
    + "দেখিয়েছে দর কোথায় হারিয়ে গেছে। এই অধ্যায় দুটিকে পাশাপাশি রাখে সেই "
    + `${tenders}টি দরপত্রের জন্য, যাদের দুটোই আছে: প্রবেশের একটি ছাপা শর্ত, আর কারা দর `
    + "দিয়েছিল তার ছাপা সংখ্যা।",
  "ch6.p2": "প্রবেশের কোনো কড়া শর্ত যদি মাঠ পাতলা করে দিত, তবে যে দরপত্রগুলিতে সবচেয়ে কড়া "
    + "ধারা আছে সেগুলিতে কম দরদাতা আর বেশি সরিয়ে রাখা দর দেখা যাওয়া উচিত। এই ভান্ডারে "
    + "সেগুলি সেদিকেই একটু হেলে আছে — আর <b>এই হেলানিটি এই নমুনার আকারে দৈবের থেকে আলাদা "
    + "করার মতো বড় নয়।</b> দুটি পরীক্ষাই তাদের p-মান সহ নিচে ছাপা হলো, যাতে পাঠক ঠিক "
    + "দেখতে পান পর্যবেক্ষণটি কতটা দুর্বল।",
  "ch6.p3": ({ dropped, one, strongOf }) =>
    `অন্তত একটি দর সরিয়ে রাখা হয়েছিল কি না: ${dropped}। ঠিক একটিমাত্র দর রেসপনসিভ থেকে `
    + `গেল কি না: ${one}। একটিও প্রচলিত সীমা ছোঁয় না। সবচেয়ে কড়া ধারার দলটিতে কেবল `
    + `${strongOf}টি দরপত্র আছে, যা প্রশ্নটি কোনো দিকেই মীমাংসা করার জন্য বড় কম। <b>এই `
    + "অনুসন্ধান দাবি করে না যে প্রবেশের অসাধারণ শর্ত এই ভান্ডারে প্রতিযোগিতা কমিয়েছে।</b> "
    + "এটি যা দাবি করে তা হলো, ভান্ডারটি প্রশ্নটির উত্তর দিতে পারে না — এবং হিসাবটি দেখিয়ে দেয়।",
