  /* ---- the evidence layer ----
     পাঠক একটি সূত্র-পৃষ্ঠার দিকে যেতে যেতে যে বাক্যগুলির মুখোমুখি হন। এগুলি যা মুড়ে
     রাখে — তুলে আনা পৃষ্ঠার লেখা, ফাইলের নাম, উদ্ধৃতি — তার কিছুই অনুবাদ করা হয় না। */
  "ev.check.one": "দলিলের সঙ্গে এটি মিলিয়ে দেখুন",
  "ev.check.many": ({ n }) => `${n}টি দলিলের সঙ্গে এটি মিলিয়ে দেখুন`,
  "ev.wholeDataset": "এই ফলটি কোনো একক পৃষ্ঠা নয়, গোটা তথ্যভান্ডারের উপর করা হিসাব; "
    + "হিসাবটি উপরে ছাপা আছে এবং যে সারণিগুলির উপর তা চলে সেগুলি ডাউনলোড অংশে আছে।",
  "ev.howWorkedOut": "কীভাবে হিসাব করা হলো:",
  "ev.loading": "পৃষ্ঠাগুলি পড়া হচ্ছে",
  "ev.docMeta": ({ kind, pages, agree }) =>
    `${kind}, ${pages} পৃষ্ঠা, দ্বিতীয় এক্সট্র্যাক্টর একমত: ${agree}`,
  "ev.notInIndex": "এই পৃষ্ঠাটি প্রমাণের সূচিতে নেই",
  "ev.quotedWords": "এই ফলটি যে শব্দগুলি উদ্ধৃত করে, যেমন তুলে আনা হয়েছে",
  "ev.showPage": "পার্সার যেভাবে পড়েছে, পৃষ্ঠাটি সেভাবে দেখান",
  "ev.page": ({ n }) => `পৃষ্ঠা ${n}`,
  "ev.pageContinues": "… পৃষ্ঠা চলছে",
  "ev.confidence": "নিশ্চয়তা:",

  /* ---- the document browser ----
     doc.itemMeta আর doc.meta এক বাক্য হিসেবে না ছেপে টুকরো জুড়ে তৈরি হয়, কারণ টুকরোগুলি
     সংখ্যা ও চিহ্ন — অনুবাদককে সেগুলি সাজানোর সুযোগ থাকা দরকার। doc.reading ও
     doc.openFile-এর ভিতরের ফাইলের নাম বসানো হয়, কখনও অনুবাদ করা হয় না। */
  "doc.filterHint": "ফাইলের নাম, দরপত্রের নম্বর বা ফোল্ডার ধরে ছেঁকে নিন…",
  "doc.loadingList": "দলিলের তালিকা লোড হচ্ছে",
  "doc.pickerAria": "ফোল্ডারের দলিলগুলি",
  "doc.choose": "কোনো দলিল থেকে তুলে আনা লেখা পড়তে সেটি বেছে নিন।",
  "doc.pages.one": ({ n }) => `${n} পৃষ্ঠা`,
  "doc.pages.many": ({ n }) => `${n} পৃষ্ঠা`,
  "doc.words.one": ({ n }) => `${n} শব্দ`,
  "doc.words.many": ({ n }) => `${n} শব্দ`,
  "doc.itemMeta": ({ folder, kind, pages, characters }) =>
    `${folder} · ${kind} · ${pages} · ${characters} অক্ষর পড়া হয়েছে`,
  "doc.matchCapped": ({ n, shown }) =>
    `${n}টি দলিল মিলেছে; প্রথম ${shown}টির তালিকা দেওয়া হলো`,
  "doc.countOf": ({ n, total }) => `${total}টি দলিলের মধ্যে ${n}টি`,
  "doc.reading": ({ file }) => `${file} পড়া হচ্ছে`,
  "doc.openFile": ({ file }) => `${file} খুলুন`,
  "doc.meta": ({ pages, words, textLayer, ocr, agree }) =>
    `${pages} · ${words} · টেক্সট লেয়ার: ${textLayer} · `
