  "down.f.text": "প্রতিটি ফলাফল যে টুকরোটি দেখায়",

  /* ---- what the search engine says about its own work ----
     search/search.js এর বাইরে কিছুই ছাপে না। এদের প্রতিটিই ইঞ্জিনের স্বীকারোক্তি — যা
     টাইপ করা হয়েছিল তা সে পায়নি, আর তার বদলে সে কী করেছে। তাই কাছাকাছি মিলকে কখনও
     মিলে যাওয়া হিসেবে দেখানো হয় না। এদের ভিতরে যা উদ্ধৃত হয়ে ফিরে আসে — যে শব্দটি টাইপ
     করা হয়েছে, সূচি যে শব্দগুলি ধরে রাখে, কোনো ঘরের নাম — তার কিছুই অনুবাদ করা হয় না:
     একটি বানানই এখানে বাক্যের বিষয়। */

  "find.prefix": ({ word, words }) =>
    `“${word}” একটি শব্দের শুরু হিসেবে পড়া হয়েছে: ${words}`,
  "find.andMore": ({ n }) => ` এবং আরও ${n}টি`,
  "find.loose": ({ word, words }) =>
    `“${word}”-এর OCR-শিথিল বানান ${words}-এর সঙ্গে মেলে`,
  "find.near": ({ word, words }) =>
    `“${word}” সূচিতে নেই; সূচিতে থাকা সবচেয়ে কাছের শব্দগুলি: ${words}`,
  "find.nowhere": ({ word, documents }) => `“${word}” ওই ${documents}টি দলিলের কোথাওই `
    + "নেই, তা থেকে তৈরি তথ্যভান্ডারেও নেই",
  "find.noField": ({ name, value }) => `কোনো নথির ${name} “${value}”-এর সঙ্গে মেলে না`,
  "find.badRange": ({ name, lo, hi }) => `${name}:${lo}..${hi} সংখ্যার জোড়া নয়`,
  "find.emptyRange": ({ name, lo, hi }) =>
    `তথ্যভান্ডারের কোনো কিছুর ${name} ${lo} ও ${hi}-এর মধ্যে নেই`,
  "find.pagesCapped": ({ phrase, more, limit }) => `“${phrase}”: আরও ${more}টি দলিল এই `
    + `শব্দগুলি সবই কোথাও ধরে রাখে; শব্দগুলি একসঙ্গে বসে আছে কি না দেখতে কেবল প্রথম `
    + `${limit}টি খোলা হয়েছে`,
  "find.wrongOrder": ({ phrase, n }) => `“${phrase}”: ${n}টি নথি এই শব্দগুলি সবই ধরে `
    + "রাখে, তবে এই ক্রমে নয়, তাই সেগুলি বাদ রাখা হলো",
  "find.onlyExclusions": "এই প্রশ্নটি কেবল কী বাদ দিতে হবে তাই বলে, তাই বাকি সবকিছুর "
    + "তালিকা দেওয়া হলো",

