  "srch.title": "এই ভান্ডার যে প্রতিটি শব্দ ছাপে, তার সবটুকুতে খুঁজুন",
  "srch.p1": "এই ঘরটি দলিলগুলি থেকেই তৈরি একটি সূচি পড়ে: পার্সার যে প্রতিটি ঘর তুলে "
    + "এনেছে, প্রবেশের প্রতিটি শর্তের প্রতিটি ধারা, প্রতিটি নাম, এবং প্রতিটি পৃষ্ঠার লেখা। "
    + "গোটাটাই চলে আপনার ব্রাউজারের ভিতরে। আপনি যা টাইপ করেন তার কিছুই কোথাও পাঠানো হয় "
    + "না, কারণ পাঠানোর জায়গাই নেই — এই সাইটের পিছনে কোনো সার্ভার নেই।",
  "srch.p2": "দলিলগুলি যে শব্দ ব্যবহার করে না, তা কিছুই ফেরায় না, এবং সে কথা বলেও দেয়। "
    + "হুবহু মিল না পেলে ঘরটি শব্দটিকে আগে একটি শব্দের শুরু হিসেবে ফের চেষ্টা করে, তারপর "
    + "স্ক্যানার যে ভুলগুলি করে তার বিপরীতে, তারপর এক-দুই অক্ষরের হেরফেরের মধ্যে — এবং এর "
    + "কোনটি সে করল তা আপনাকে জানায়। কাছাকাছি মিলকে কখনও মিলে যাওয়া হিসেবে দেখানো হয় না।",

