  /* ============================================================================
     পার্সারের নিজের শব্দভান্ডার — word() দিয়ে খোঁজা হয়, t() দিয়ে নয়

     এখান থেকে নিচের সব ঘরই খোলা তালিকা। word(key, fallback) কোনো ঘর না পেলে চিৎকার করে
     না, পাইপলাইন নিজে যে টোকেনটি লিখেছিল সেটিই ছাপে। ইংরেজি প্যাক তাই এদের প্রায় সবই
     ছেড়ে দিয়েছে — সেখানে CSV-র নিজের শব্দটিই শব্দ, আর তা ছেড়ে দেওয়ার মানে উপরের দিকে
     কোনো কলামের নাম বদলালে পৃষ্ঠায় সেটি দেখা যাবে, চাপা পড়বে না। বাংলায় টোকেনটি শব্দ নয়,
     তাই এই প্যাক প্রত্যেকটির নাম ধরে লেখে।

     ঘরের নামগুলি (ডানদিকের চাবিটি) কখনও অনুবাদ করা হয় না — সেগুলি তথ্যভান্ডারের চাবি।
     csvcol.* এখানে নেই, এবং কেন নেই তা tbl.* ব্লকের উপরে লেখা আছে। */

